import {EXPEDITION_ACTION_TYPES,applyExpeditionAction,projectExpedition} from './expedition.js';
import {CARD_CATALOG,CARD_MAP,STAGES,STARTER_IDS} from './catalog.js';
export {CARD_CATALOG,STAGES} from './catalog.js';
export class CardRuleError extends Error {constructor(code,message){super(message);this.name='CardRuleError';this.code=code;}}
const fail=(code,message)=>{throw new CardRuleError(code,message);};
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const exact=(action,allowed)=>{if(!action||typeof action!=='object'||Array.isArray(action)||Object.keys(action).some(key=>!allowed.includes(key)))fail('invalid_action','這個操作無法辨識。');};
function rng(state){let h=2166136261;for(const c of `${state.seed}:${state.counter++}`)h=Math.imul(h^c.charCodeAt(0),16777619);h+=h<<13;h^=h>>>7;h+=h<<3;h^=h>>>17;h+=h<<5;return(h>>>0)/4294967296;}
export function createCardState(seed){if(typeof seed!=='string'||seed.length<8||seed.length>256)fail('invalid_seed','無法建立卡冊。');return{version:1,revision:0,seed,counter:0,tickets:15,shards:0,collection:Object.fromEntries(STARTER_IDS.map(id=>[id,{copies:1,level:1}])),deck:['person-jack','person-captain','person-jonathan'],loadout:{item:'item-badge',event:'event-drink'},campaign:{completed:[]},drawPity:0,totalDraws:0,battle:null,lastResult:null};}
export function projectCardState(state){const{seed,counter,...safe}=structuredClone(state);if(safe.expedition)safe.expedition=projectExpedition(safe.expedition);return safe;}
function own(state,id,kind){const card=typeof id==='string'&&Object.hasOwn(CARD_MAP,id)?CARD_MAP[id]:null;if(!card||!Object.hasOwn(state.collection,id)||(kind&&card.kind!==kind))fail('not_owned','請選擇卡冊裡的對應卡片。');return card;}
const levelOf=(s,id)=>s.collection[id]?.level||1;
export const upgradeCost=level=>Math.max(1,level)*5;
export const craftCost=rarity=>({N:8,R:22,SSR:70}[rarity]||Infinity);
function draw(state,action){exact(action,['type','count','banner']);if(![1,10].includes(action.count)||!['all','character','item','event'].includes(action.banner))fail('invalid_action','請選擇單抽或十連與卡池。');if(state.battle?.status==='active')fail('in_battle','挑戰結束後再回卡池。');if(state.tickets<action.count)fail('not_enough_tickets','抽卡券不足；通過新關卡或完成人生可以取得。');state.tickets-=action.count;const cards=[];let guaranteed=false;for(let i=0;i<action.count;i++){state.drawPity++;const roll=rng(state);let rarity=state.drawPity>=20?'SSR':roll<.06?'SSR':roll<.30?'R':'N';if(action.count===10&&i===9&&!guaranteed&&rarity==='N')rarity='R';if(rarity==='SSR')state.drawPity=0;if(rarity!=='N')guaranteed=true;const pool=CARD_CATALOG.filter(c=>c.rarity===rarity&&(action.banner==='all'||c.kind===action.banner));const card=pool[Math.floor(rng(state)*pool.length)];let duplicate=false,shards=0;if(state.collection[card.id]){duplicate=true;state.collection[card.id].copies++;shards={N:2,R:6,SSR:18}[rarity];state.shards+=shards;}else state.collection[card.id]={copies:1,level:1};cards.push({id:card.id,duplicate,shards});state.totalDraws++;}state.lastResult={type:'draw',cards,count:action.count,banner:action.banner};}
export function itemPower(card,level=1){return card.power+(level-1)*({heal:4,shield:3,pressure:2,focus:2,expose:1,drain:.5}[card.effect]||0);}
export function eventPower(card,level=1){const tier={N:1,R:2,SSR:3}[card.rarity];const base={heal:[12,24,38],shield:[10,20,34],damage:[20,42,68],charge:[0,18,36],expose:[4,8,14],weaken:[5,9,14]}[card.effect][tier-1];return base+(level-1)*({heal:4,shield:4,damage:6,charge:6,expose:2,weaken:2}[card.effect]);}
export function eventDescription(card,level=1){const power=eventPower(card,level);switch(card.effect){case'heal':return card.description.replace(/全隊恢復 \d+ 生命/,`全隊各恢復最多 ${power} 生命`);case'shield':return card.description.replace(/全隊獲得 \d+ 護盾/,`全隊各獲得 ${power} 護盾`);case'damage':return card.description.replace(/造成 \d+ 傷害/,`造成 ${power} 基礎傷害（會扣除防禦）`);case'charge':return `全隊技能冷卻歸零${power>0?`，額外造成 ${power} 基礎傷害（會扣除防禦）`:''}。`;case'expose':return card.description.replace(/本場破防增加 \d+/,`本場敵方防禦降低 ${power}`);case'weaken':return card.description.replace(/敵方下三次攻擊降低 \d+/,`敵方下三次攻擊降低 ${power}`);default:return card.description;}}
function partyStats(state,id){const card=CARD_MAP[id],level=levelOf(state,id),item=CARD_MAP[state.loadout.item],power=itemPower(item,levelOf(state,state.loadout.item));return{id,hp:card.hp+(level-1)*12+(item.effect==='heal'?power:0),maxHp:card.hp+(level-1)*12+(item.effect==='heal'?power:0),attack:card.attack+(level-1)*4+(item.effect==='pressure'?power:0),shield:item.effect==='shield'?power:0,cooldown:0,boost:0};}
function startBattle(state,action){exact(action,['type','stage']);const stage=STAGES.find(s=>s.id===action.stage);if(!stage)fail('invalid_stage','沒有這一關。');if(state.battle?.status==='active')fail('in_battle','先結束目前挑戰。');if(stage.id>1&&!state.campaign.completed.includes(stage.id-1))fail('stage_locked','請先通過前一關。');state.deck.forEach(id=>own(state,id,'character'));const item=own(state,state.loadout.item,'item');state.battle={stage:stage.id,status:'active',round:1,party:state.deck.map(id=>partyStats(state,id)),enemy:{hp:stage.hp,maxHp:stage.hp,attack:Math.max(3,stage.attack-(item.effect==='drain'?Math.floor(itemPower(item,levelOf(state,item.id))):0)),armor:Math.max(0,stage.armor-(item.effect==='expose'?itemPower(item,levelOf(state,item.id)):0)),weaken:0,weakenTurns:0},eventUsed:false,log:[`挑戰開始：${stage.name}。先選一位出手，再選策略。`],reward:0};state.lastResult={type:'battle-start',stage:stage.id};}
function hurtEnemy(battle,raw){const amount=Math.max(1,Math.round(raw)-battle.enemy.armor);battle.enemy.hp=Math.max(0,battle.enemy.hp-amount);return amount;}
function lowest(party){return party.filter(p=>p.hp>0).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];}
function battleTurn(state,action){exact(action,['type','move','target']);if(!['strike','guard','skill','event'].includes(action.move)||('target'in action&&(!Number.isInteger(action.target)||action.target<0||action.target>2)))fail('invalid_action','請選擇出手角色與策略。');const b=state.battle;if(!b||b.status!=='active')fail('no_battle','目前沒有進行中的挑戰。');const target=action.target??0,actor=b.party[target],card=CARD_MAP[actor.id];if(actor.hp<=0)fail('knocked_out','這位角色正在休息，請換另一位。');const notes=[];if(action.move==='skill'&&actor.cooldown>0)fail('cooldown','這位角色的技能還在冷卻。');if(action.move==='event'&&b.eventUsed)fail('event_used','事件卡本場已使用。');for(const p of b.party)p.cooldown=Math.max(0,p.cooldown-1);if(action.move==='strike'){notes.push(`${card.name}出手，造成 ${hurtEnemy(b,actor.attack+actor.boost)} 傷害。`);actor.boost=0;}else if(action.move==='guard'){for(const p of b.party)if(p.hp>0)p.shield+=8+levelOf(state,actor.id)*2;actor.hp=Math.min(actor.maxHp,actor.hp+7);notes.push(`${card.name}掩護全隊，增加護盾並喘一口氣。`);}else if(action.move==='skill'){const level=levelOf(state,actor.id),item=CARD_MAP[state.loadout.item],extra=item.effect==='focus'?itemPower(item,levelOf(state,item.id)):0;actor.cooldown=3;switch(card.effect){case'heal':{const p=lowest(b.party),heal=24+level*6;p.hp=Math.min(p.maxHp,p.hp+heal);notes.push(`${card.name}使出「${card.skill}」，${CARD_MAP[p.id].name}恢復 ${heal} 生命。`);break;}case'shield':for(const p of b.party)if(p.hp>0)p.shield+=13+level*3;notes.push(`${card.name}使出「${card.skill}」，全隊獲得護盾，並造成 ${hurtEnemy(b,actor.attack*.8+extra)} 傷害。`);break;case'expose':b.enemy.armor=Math.max(0,b.enemy.armor-3-level);notes.push(`${card.name}使出「${card.skill}」，削弱防禦，造成 ${hurtEnemy(b,actor.attack+extra)} 傷害。`);break;case'focus':actor.boost=10+level*3;notes.push(`${card.name}使出「${card.skill}」，造成 ${hurtEnemy(b,actor.attack*1.5+extra)} 傷害，下次普通出手強化。`);break;case'drain':b.enemy.weaken=6+level*2;b.enemy.weakenTurns=1;notes.push(`${card.name}使出「${card.skill}」，造成 ${hurtEnemy(b,actor.attack+extra)} 傷害，打斷下一次攻勢。`);break;default:notes.push(`${card.name}使出「${card.skill}」，造成 ${hurtEnemy(b,actor.attack*1.8+extra)} 傷害。`);}}else{const event=own(state,state.loadout.event,'event'),level=levelOf(state,event.id),power=eventPower(event,level);let effectNote='';b.eventUsed=true;switch(event.effect){case'heal':{let healed=0;for(const p of b.party)if(p.hp>0){const before=p.hp;p.hp=Math.min(p.maxHp,p.hp+power);healed+=p.hp-before;}effectNote=`全隊合計恢復 ${healed} 生命，每人最多 ${power}。`;break;}case'shield':for(const p of b.party)if(p.hp>0)p.shield+=power;effectNote=`在場隊員各獲得 ${power} 護盾。`;break;case'damage':effectNote=`造成 ${hurtEnemy(b,power)} 傷害。`;break;case'charge':for(const p of b.party)p.cooldown=0;effectNote=`全隊技能冷卻歸零${power>0?`，另造成 ${hurtEnemy(b,power)} 傷害`:''}。`;break;case'expose':{const before=b.enemy.armor;b.enemy.armor=Math.max(0,b.enemy.armor-power);effectNote=`敵方防禦 ${before} → ${b.enemy.armor}。`;break;}case'weaken':b.enemy.weaken=power;b.enemy.weakenTurns=3;effectNote=`敵方接下來三次攻擊降低 ${power}。`;break;}notes.push(`發動事件「${event.name}」：${effectNote}`);}
 if(b.enemy.hp<=0){b.status='won';const stage=STAGES[b.stage-1],first=!state.campaign.completed.includes(b.stage);if(first){state.campaign.completed.push(b.stage);state.campaign.completed.sort((a,b)=>a-b);state.tickets+=stage.reward;state.shards+=8+b.stage*2;b.reward=stage.reward;notes.push(`首次過關！取得 ${stage.reward} 張抽卡券與 ${8+b.stage*2} 碎片。`);}else notes.push('再次過關！這次是練習，不重複發放首勝獎勵。');}
 else{const living=b.party.map((p,i)=>({p,i})).filter(({p})=>p.hp>0);const hit=living[(b.round-1)%living.length];const strong=b.round%3===0,raw=Math.max(2,b.enemy.attack+(strong?6:0)-(b.enemy.weakenTurns>0?b.enemy.weaken:0)),blocked=Math.min(hit.p.shield,raw);hit.p.shield-=blocked;hit.p.hp=Math.max(0,hit.p.hp-(raw-blocked));notes.push(`${strong?'對方蓄力攻勢':'對方反擊'} → ${CARD_MAP[hit.p.id].name}：${raw-blocked} 傷害${blocked?`，護盾擋下 ${blocked}`:''}。`);if(b.enemy.weakenTurns>0)b.enemy.weakenTurns--;if(!b.party.some(p=>p.hp>0)){b.status='lost';notes.push('本次挑戰失敗。卡片不會損失；調整隊伍再來。');}else if(b.round>=60){b.status='lost';notes.push('會議拖到散場，本次挑戰結束。調整火力再來。');}b.round++;}b.log=[...b.log,...notes].slice(-18);state.lastResult={type:'battle-turn',status:b.status,notes};}
export function applyCardAction(previous,action){if(!previous||previous.version!==1||!Number.isSafeInteger(previous.revision))fail('invalid_state','卡冊版本無法辨識。');const state=structuredClone(previous);if(!action||typeof action.type!=='string')fail('invalid_action','缺少操作。');if(EXPEDITION_ACTION_TYPES.includes(action.type)){applyExpeditionAction(state,action,{rng,fail});state.revision++;return state;}if(state.expedition?.status==='active')fail('in_expedition','先完成或撤退這輪冒險，再調整永久卡冊。');switch(action.type){case'draw':draw(state,action);break;case'set-deck':{exact(action,['type','characters','item','event']);if(state.battle?.status==='active')fail('in_battle','挑戰結束後才能調整隊伍。');if(!Array.isArray(action.characters)||action.characters.length!==3||new Set(action.characters).size!==3)fail('invalid_deck','請選三位不同人物。');action.characters.forEach(id=>own(state,id,'character'));own(state,action.item,'item');own(state,action.event,'event');state.deck=[...action.characters];state.loadout={item:action.item,event:action.event};state.lastResult={type:'deck'};break;}case'upgrade':{exact(action,['type','cardId']);if(state.battle?.status==='active')fail('in_battle','挑戰結束後再升級卡片。');own(state,action.cardId);const entry=state.collection[action.cardId];if(entry.level>=5)fail('max_level','已達最高等級 Lv.5。');const cost=upgradeCost(entry.level);if(state.shards<cost)fail('not_enough_shards','碎片不足。');state.shards-=cost;entry.level++;state.lastResult={type:'upgrade',cardId:action.cardId,level:entry.level};break;}case'craft':{exact(action,['type','cardId']);if(state.battle?.status==='active')fail('in_battle','挑戰結束後再製作卡片。');const card=CARD_MAP[action.cardId];if(!card||state.collection[card.id])fail('invalid_craft','只能製作尚未擁有的卡片。');const cost=craftCost(card.rarity);if(state.shards<cost)fail('not_enough_shards','碎片不足。');state.shards-=cost;state.collection[card.id]={copies:1,level:1};state.lastResult={type:'craft',cardId:card.id};break;}case'start-battle':startBattle(state,action);break;case'battle-turn':battleTurn(state,action);break;case'abandon-battle':exact(action,['type']);if(!state.battle||state.battle.status!=='active')fail('no_battle','目前沒有進行中的挑戰。');state.battle.status='abandoned';state.battle.log.push('你收起卡片，決定先調整隊伍。本次沒有首勝獎勵。');state.lastResult={type:'battle-abandoned'};break;default:fail('invalid_action','這個操作無法辨識。');}state.revision++;return state;}
export function lifeTicketReward(score,workRounds){if(!Number.isSafeInteger(score)||score<0||score>10000||!Number.isSafeInteger(workRounds)||workRounds<0||workRounds>10000)fail('invalid_claim','人生紀錄的數值不完整。');return workRounds<3?0:Math.min(12,1+Math.floor(score/1000)+Math.floor(workRounds/6));}
export function grantLifeTickets(previous,claim){if(!claim||typeof claim.runId!=='string'||claim.runId.length>160)fail('invalid_claim','缺少人生紀錄。');const amount=lifeTicketReward(claim.score,claim.workRounds),state=structuredClone(previous);state.tickets+=amount;state.revision++;state.lastResult={type:'life-reward',tickets:amount,runId:claim.runId};return state;}
